from __future__ import annotations

import base64
import os
import subprocess
import sys
from pathlib import Path

# Kaggle CLI script kernels upload the primary code_file reliably, but auxiliary
# directories may not be preserved. Embed the helper modules in this file and
# materialize them at runtime so the job is self-contained.
EMBEDDED = {'bridge_task_abc.py': '', 'oxe_task_abc.py': '', 'task_abc_continual.py': ''}

WORK = Path('/kaggle/working/neurobot_taskabc')
SRC = WORK / 'src'


def run(*args: str) -> None:
    print('+', ' '.join(args), flush=True)
    subprocess.run(list(args), check=True, cwd=WORK)


def ensure_package(import_name: str, pip_spec: str) -> None:
    try:
        __import__(import_name)
    except ImportError:
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', pip_spec], check=True)


def materialize_sources() -> None:
    SRC.mkdir(parents=True, exist_ok=True)
    for name, payload in EMBEDDED.items():
        path = SRC / name
        path.write_bytes(base64.b64decode(payload))
        print(f'Materialized {path} ({path.stat().st_size} bytes)')


def main() -> None:
    print('NeuroBot-Plasticity real-data Task A→B→C run — self-contained v4 RLDS/OXE Bridge schema fix')
    print('Termux is the controller; Kaggle is the training machine.')
    WORK.mkdir(parents=True, exist_ok=True)
    materialize_sources()
    subprocess.run(['nvidia-smi'], check=True)
    ensure_package('tensorflow_datasets', 'tensorflow-datasets>=4.9,<5')

    print('Bridge parser supports both catalog and OXE schemas: root language_instruction or observation.natural_language_instruction; flat or dict actions.', flush=True)
    run(
        sys.executable, str(SRC / 'bridge_task_abc.py'),
        '--output-dir', 'data/bridge_abc',
        '--samples-per-task', '800',
        '--max-scan-episodes', '3000',
        '--max-steps-per-episode', '40',
    )
    run(
        sys.executable, str(SRC / 'task_abc_continual.py'),
        '--task-dir', 'data/bridge_abc',
        '--output-dir', 'outputs/bridge_abc',
        '--epochs', '10',
        '--replay-fraction', '0.30',
        '--replay-size-per-task', '1200',
    )

    run(
        sys.executable, str(SRC / 'oxe_task_abc.py'),
        '--output-dir', 'data/oxe_abc',
        '--samples-per-task', '1500',
        '--max-episodes-per-dataset', '300',
        '--max-steps-per-episode', '32',
    )
    run(
        sys.executable, str(SRC / 'task_abc_continual.py'),
        '--task-dir', 'data/oxe_abc',
        '--output-dir', 'outputs/oxe_abc',
        '--epochs', '10',
        '--replay-fraction', '0.30',
        '--replay-size-per-task', '900',
    )

    print('\nCompleted both real-data Task A→B→C experiments.')
    print('Bridge outputs:', WORK / 'outputs/bridge_abc')
    print('OXE outputs:', WORK / 'outputs/oxe_abc')


if __name__ == '__main__':
    main()
